//! `BlockIdUsage`.

use crate::api::*;
use lq_syntax::Node;

pub const IMPL: CheckImpl = CheckImpl::Liquid {
    create,
    enter: NodeMask::of(&[NodeKind::Comparison, NodeKind::VariableLookup]),
    exit: NodeMask::NONE,
};

fn create<'a, 'f>(_cx: &LiquidCx<'a, 'f>) -> Option<Box<dyn LiquidCheck<'a> + 'a>> {
    Some(Box::new(Check))
}

struct Check;

const MESSAGE: &str =
    "The ID is dynamically generated by Shopify and is subject to change. You should avoid relying on a literal value of this ID.";

/// `isUsingBlockId(node)`.
fn is_using_block_id(node: &Node<'_>) -> bool {
    matches!(node, Node::VariableLookup(l)
        if l.name == Some("block") && matches!(l.lookups.first(), Some(Node::String(s)) if s.value == "id"))
}

impl<'a> LiquidCheck<'a> for Check {
    fn enter(&mut self, node: &'a Node<'a>, ancestors: &[&'a Node<'a>], cx: &LiquidCx<'a, '_>) {
        let flagged = match node {
            Node::Comparison(c) => c.comparator == "==" && is_using_block_id(&c.left),
            Node::VariableLookup(_) => {
                matches!(ancestors.last(), Some(Node::LiquidTag(t)) if t.name == "case") && is_using_block_id(node)
            }
            _ => false,
        };
        if flagged {
            let p = node.position();
            cx.report(LiquidProblem::new(MESSAGE, p.start, p.end));
        }
    }
}
